    "cannyTraceEdgesqzisz": "Canny (trace edges)",
    "shrinksTheTextEncoder4a0g2": "Shrinks the text encoder to save memory, at some cost to image quality. Default lets the model choose, which on Qwen-Image 2.1 means its hosted FP8 encoder (8.75 GB rather than 16.3); pick Dense (bf16) to pin the released encoder. FP8 (storage) is the safe pick and the only one that works with CPU offload. FP8 (compute) needs an RTX 40 series or newer.{p1} The loaded build below reports what was applied.",
